class Solution:
    def countAssignments(self, A: int, B: int, C: int, D: int) -> int:
        # Inclusion-exclusion over the k tasks that nobody takes.
        total = 0
        for k in range(A + 1):
            free = A - k
            total += (-1) ** k * math.comb(A, k) * math.comb(free, B) * math.comb(free, C) * math.comb(free, D)
        return total % (10**9 + 7)

