class Solution {
public:
    int countAssignments(int A, int B, int C, int D) {
        const long long MOD = 1000000007;
        vector<vector<long long>> c(31, vector<long long>(31, 0));
        for (int i = 0; i <= 30; i++) { c[i][0] = 1; for (int j = 1; j <= i; j++) c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD; }
        auto C_ = [&](int n, int k) { return (k < 0 || k > n) ? 0LL : c[n][k]; };
        long long total = 0;
        for (int k = 0; k <= A; k++) {
            long long t = C_(A, k) * C_(A - k, B) % MOD * C_(A - k, C) % MOD * C_(A - k, D) % MOD;
            total = (total + (k % 2 ? MOD - t : t)) % MOD;
        }
        return (int) total;
    }
};

